// Inscrits consentants pour l'alerte « nouveau stock local » (email 04) : statut confirmé, non désinscrit,
// alerte demandée sur ce produit ou préférence de format correspondante. Aucune adresse n'est manipulée ici :
// l'outil d'emailing envoie à partir de l'identifiant d'inscrit.
const reception = $('Réception contrôlée (passerelle agent 11)').first().json.body || {};
const data = $input.first().json;
const subscribers = data && Array.isArray(data.subscribers) ? data.subscribers : null;
if (!subscribers) return []; // outil d'emailing non branché : aucun envoi
const format = String(reception.format_preference || '').toLowerCase();
return subscribers
  .filter((s) => s.status === 'confirme' && s.unsubscribed !== true)
  .filter((s) => (Array.isArray(s.alert_products) && s.alert_products.includes(reception.product_key))
    || (format && Array.isArray(s.formats) && s.formats.includes(format)))
  .map((s) => ({ json: { subscriber_id: String(s.id), product_key: reception.product_key, public_title: reception.public_title, public_url: reception.public_url } }));

// Demande d'avis (email 11) : une seule par commande, aucune réclamation ouverte, client non opposé (note C3).
const data = $input.first().json;
const order = data && data.data ? data.data.order : null;
if (!order) return []; // lecture Shopify non configurée : aucun envoi
const tags = (order.tags || []).map((t) => String(t).toLowerCase());
if (tags.includes('reclamation') || tags.includes('avis-refus')) return [];
if (!order.customer || !order.customer.id) return [];
return [{ json: { customer_id: String(order.customer.id), order_name: order.name } }];

// Lien public d'un email (jeton unique, EMAILS §4 règle 7). Jeton absent ou mal formé : la demande ne peut pas être
// identifiée — elle n'est JAMAIS ignorée en silence (page d'erreur honnête et, pour une opposition, incident).
const item = $input.first().json;
const token = item.query && item.query.jeton ? String(item.query.jeton) : '';
const valide = /^[A-Za-z0-9_-]{16,128}$/.test(token);
return [{ json: { etape: 'normalise', valide, jeton: valide ? token : null, received_at: new Date().toISOString() } }];

// Résultat de l'outil d'emailing -> préparation de l'étape Shopify (client lié au jeton, s'il existe).
// Nœud désactivé (outil non branché) : la donnée normalisée passe telle quelle => « non branché », jamais « confirmé ».
const j = $input.first().json || {};
const lien = $('Normaliser le lien de désinscription').first().json;
let emailing;
if (j.error) emailing = `échec (${(j.error && j.error.message) || 'erreur'})`;
else if (j.etape === 'normalise') emailing = 'non branché (nœud désactivé)';
else emailing = j.unsubscribed === true ? 'confirmé' : 'réponse non conforme';
const customer = emailing === 'confirmé' && j.shopify_customer_id ? String(j.shopify_customer_id).replace(/\D/g, '') : '';
return [{ json: { etape: 'prepare', jeton: lien.jeton, emailing, shopify_customer_id: customer || null,
  shopify_applicable: customer !== '' } }];

// Bilan : seul un résultat CONFIRMÉ par chaque outil compte ; nœud désactivé, erreur ou réponse non conforme => non
// confirmé (incident pour un traitement manuel sans délai, envois marketing suspendus jusqu'à la reprise).
const prep = $('Préparer l’étape Shopify (désinscription)').first().json;
const j = $input.first().json || {};
let shopify;
if (!prep.shopify_applicable) shopify = prep.emailing === 'confirmé' ? 'sans objet (aucun client Shopify lié)' : 'non vérifié';
else if (j.error) shopify = `échec (${(j.error && j.error.message) || 'erreur'})`;
else if (j.etape === 'prepare') shopify = 'non branché (nœud désactivé)';
else {
  const r = j.data && j.data.customerEmailMarketingConsentUpdate;
  shopify = r && Array.isArray(r.userErrors) && r.userErrors.length === 0 ? 'confirmé' : 'réponse non conforme';
}
const ok = prep.emailing === 'confirmé' && (!prep.shopify_applicable || shopify === 'confirmé');
return [{ json: { tous_confirmes: ok, jeton: prep.jeton, resume: `outil d’emailing : ${prep.emailing} ; Shopify : ${shopify}` } }];

// Consentement marketing retiré dans Shopify : à propager à l'outil d'emailing. Journal sans adresse.
const item = $input.first().json;
return [{ json: { etape: 'normalise', shopify_customer_id: String(item.id || ''), received_at: new Date().toISOString() } }];

// Bilan de la propagation Shopify -> outil d'emailing : seul un retrait confirmé par l'outil compte.
const j = $input.first().json || {};
let emailing;
if (j.error) emailing = `échec (${(j.error && j.error.message) || 'erreur'})`;
else if (j.etape === 'normalise') emailing = 'non branché (nœud désactivé)';
else emailing = j.unsubscribed === true ? 'confirmé' : 'réponse non conforme';
return [{ json: { tous_confirmes: emailing === 'confirmé', resume: `outil d’emailing : ${emailing} ; Shopify : retrait déjà fait (origine)` } }];

// Lien public d'un email (jeton unique, EMAILS §4 règle 7). Jeton absent ou mal formé : la demande ne peut pas être
// identifiée — elle n'est JAMAIS ignorée en silence (page d'erreur honnête et, pour une opposition, incident).
const item = $input.first().json;
const token = item.query && item.query.jeton ? String(item.query.jeton) : '';
const valide = /^[A-Za-z0-9_-]{16,128}$/.test(token);
return [{ json: { etape: 'normalise', valide, jeton: valide ? token : null, received_at: new Date().toISOString() } }];

// Résultat de l'outil d'emailing -> préparation de l'étape Shopify (client lié au jeton, s'il existe).
// Nœud désactivé (outil non branché) : la donnée normalisée passe telle quelle => « non branché », jamais « confirmé ».
const j = $input.first().json || {};
const lien = $('Normaliser le lien de refus d’avis').first().json;
let emailing;
if (j.error) emailing = `échec (${(j.error && j.error.message) || 'erreur'})`;
else if (j.etape === 'normalise') emailing = 'non branché (nœud désactivé)';
else emailing = j.opted_out === true ? 'confirmé' : 'réponse non conforme';
const customer = emailing === 'confirmé' && j.shopify_customer_id ? String(j.shopify_customer_id).replace(/\D/g, '') : '';
return [{ json: { etape: 'prepare', jeton: lien.jeton, emailing, shopify_customer_id: customer || null,
  shopify_applicable: customer !== '' } }];

// Bilan : seul un résultat CONFIRMÉ par chaque outil compte ; nœud désactivé, erreur ou réponse non conforme => non
// confirmé (incident pour un traitement manuel sans délai, envois marketing suspendus jusqu'à la reprise).
const prep = $('Préparer l’étape Shopify (refus d’avis)').first().json;
const j = $input.first().json || {};
let shopify;
if (!prep.shopify_applicable) shopify = prep.emailing === 'confirmé' ? 'sans objet (aucun client Shopify lié)' : 'non vérifié';
else if (j.error) shopify = `échec (${(j.error && j.error.message) || 'erreur'})`;
else if (j.etape === 'prepare') shopify = 'non branché (nœud désactivé)';
else {
  const r = j.data && j.data.tagsAdd;
  shopify = r && Array.isArray(r.userErrors) && r.userErrors.length === 0 ? 'confirmé' : 'réponse non conforme';
}
const ok = prep.emailing === 'confirmé' && (!prep.shopify_applicable || shopify === 'confirmé');
return [{ json: { tous_confirmes: ok, jeton: prep.jeton, resume: `outil d’emailing : ${prep.emailing} ; Shopify : ${shopify}` } }];

// Lien public d'un email (jeton unique, EMAILS §4 règle 7). Jeton absent ou mal formé : la demande ne peut pas être
// identifiée — elle n'est JAMAIS ignorée en silence (page d'erreur honnête et, pour une opposition, incident).
const item = $input.first().json;
const token = item.query && item.query.jeton ? String(item.query.jeton) : '';
const valide = /^[A-Za-z0-9_-]{16,128}$/.test(token);
return [{ json: { etape: 'normalise', valide, jeton: valide ? token : null, received_at: new Date().toISOString() } }];

// Page de préférences : adresse https fournie par l'outil d'emailing ; sinon page honnête qui offre la désinscription.
const j = $input.first().json || {};
const lien = $('Normaliser le lien de préférences').first().json;
const url = !j.error && j.etape !== 'normalise' && typeof j.preferences_url === 'string' && /^https:\/\//.test(j.preferences_url)
  ? j.preferences_url : null;
return [{ json: { preferences_url: url, html: "<!DOCTYPE html><html lang=\"fr-CH\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"robots\" content=\"noindex, nofollow\"><title>Vos préférences</title><style>body{font-family:system-ui,sans-serif;max-width:40rem;margin:2rem auto;padding:0 1rem;line-height:1.5}</style></head><body><main><h1>Vos préférences</h1><p>La page de préférences n'est pas disponible pour le moment.</p><p>Pour ne plus recevoir aucun email : <a href=\"alertes-desinscrire?jeton=__JETON__\">se désinscrire</a>. Pour modifier vos choix, écrivez à REMPLACER-email-support@exemple.invalid.</p><p><a href=\"https://REMPLACER-URL-LANDING.exemple.invalid/\">Retour à l'accueil</a></p></main></body></html>".replace('__JETON__', lien.jeton) } }];

// Lien public d'un email (jeton unique, EMAILS §4 règle 7). Jeton absent ou mal formé : la demande ne peut pas être
// identifiée — elle n'est JAMAIS ignorée en silence (page d'erreur honnête et, pour une opposition, incident).
const item = $input.first().json;
const token = item.query && item.query.jeton ? String(item.query.jeton) : '';
const valide = /^[A-Za-z0-9_-]{16,128}$/.test(token);
return [{ json: { etape: 'normalise', valide, jeton: valide ? token : null, received_at: new Date().toISOString() } }];

// Double opt-in : seule une confirmation explicite de l'outil d'emailing ({ confirmed: true }) active les alertes.
const j = $input.first().json || {};
return [{ json: { confirmed: !j.error && j.etape !== 'normalise' && j.confirmed === true } }];

// Signal de demande AGRÉGÉ par référence (POST /predrop/demand) : nombre d'inscrits CONFIRMÉS, non désinscrits, qui
// suivent la référence. Aucune adresse ni identifiant d'inscrit ne sort de ce nœud : un nombre par référence.
const data = $input.first().json || {};
const subscribers = Array.isArray(data.subscribers) ? data.subscribers : null;
if (!subscribers) return []; // outil d'emailing non branché : aucun signal (pré-drop fermé faute de demande)
const counts = {};
for (const s of subscribers) {
  if (!s || s.status !== 'confirme' || s.unsubscribed === true) continue;
  const products = Array.isArray(s.alert_products) ? Array.from(new Set(s.alert_products.map(String))) : [];
  for (const key of products) {
    if (/^[A-Za-z0-9][A-Za-z0-9_.:#/-]{0,119}$/.test(key)) counts[key] = (counts[key] || 0) + 1;
  }
}
const asOf = new Date().toISOString();
return Object.keys(counts).sort().map((key) => ({ json: {
  product_key: key,
  interested_consenting_subscribers: counts[key],
  as_of: asOf,
  source: "outil d'emailing : inscrits confirmés qui suivent la référence (compte agrégé)",
} }));

// Une annonce par étape et par pré-drop : fenêtre prioritaire (inscrits consentants qui suivent la référence),
// puis ouverture à tous. L'étape vient du MOTEUR (statut calculé : paramètres signés, quota, gel, quarantaine,
// stop-loss) ; rien n'est annoncé pour des réservations fermées. Mémoire : données statiques du workflow.
// Aucune fausse urgence : ni quantité, ni heure de fermeture, ni compte à rebours dans les variables de l'email.
const memo = $getWorkflowStaticData('global');
memo.predrops = memo.predrops || {};
const data = $input.first().json || {};
const internal = Array.isArray(data.internal) ? data.internal : [];
const out = [];
for (const p of internal) {
  if (!p || p.status !== 'OPEN' || p.accepting !== true) continue;
  if (p.phase !== 'prioritaire' && p.phase !== 'ouvertes') continue;
  const seen = memo.predrops[p.predrop_id];
  if (seen === p.phase || (seen === 'ouvertes' && p.phase === 'prioritaire')) continue;
  memo.predrops[p.predrop_id] = p.phase;
  out.push({ json: {
    predrop_id: String(p.predrop_id),
    product_key: p.product_key,
    etape: p.phase,
    date_drop: p.drop_date,
    opens_at: p.opens_at || null,
    url_reservation: p.reservation_handle ? `/products/${p.reservation_handle}` : null,
    alert_tag: p.alert_tag || null,
  } });
}
return out;

// Destinataires d'une annonce de pré-drop : inscrits CONFIRMÉS, non désinscrits, qui suivent la référence (alerte
// produit). Aucune adresse ici : l'outil d'emailing envoie par identifiant d'inscrit. Outil non branché : personne.
// Revue pré-drop (PDL-08) : l'email 16 (accès prioritaire) ne part qu'aux inscrits dont l'accès est réellement
// attestable — compte client Shopify LIÉ (étiquette alerte-produit posée) et inscription CONFIRMÉE AVANT l'ouverture
// des réservations ; les autres ne reçoivent rien pendant la fenêtre prioritaire (email 17 à l'ouverture à tous).
const steps = $('Étapes à annoncer (une par pré-drop)').all();
const out = [];
$input.all().forEach((item, i) => {
  const step = (steps[i] || {}).json;
  const subscribers = item.json && Array.isArray(item.json.subscribers) ? item.json.subscribers : null;
  if (!step || !subscribers) return;
  const opens = step.opens_at ? Date.parse(step.opens_at) : NaN;
  subscribers
    .filter((s) => s && s.status === 'confirme' && s.unsubscribed !== true)
    .filter((s) => Array.isArray(s.alert_products) && s.alert_products.includes(step.product_key))
    .filter((s) => {
      if (step.etape !== 'prioritaire') return true;
      const confirmedAt = Date.parse(s.date_consentement || s.confirmed_at || '');
      return !!s.shopify_customer_id && Number.isFinite(confirmedAt) && Number.isFinite(opens) && confirmedAt <= opens;
    })
    .forEach((s) => out.push({ json: Object.assign({}, step, {
      subscriber_id: String(s.id),
      shopify_customer_id: s.shopify_customer_id ? String(s.shopify_customer_id).replace(/\D/g, '') : '',
    }) }));
});
return out;
